    {
      "id": "R1.S1",
      "evidence": "Man passes through the cart.",
      "symptom_ko": "남자가 카트를 뚫고 지나감(통과함)",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "Man passes through the cart",
      "explicit_detail_evidence": ["passes through"],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R2",
  "summary_ko": "카트의 속도에 비해 남자가 튕겨져 나갈 정도로 갑작스럽게 정지함",
  "claims": [
    {
      "id": "R2.S1",
      "evidence": "The speed of the cart does not warrant an abrupt stop for man to fly out.",
      "symptom_ko": "카트의 주행 속도에 맞지 않게 남자가 튕겨 나갈 정도로 카트가 급정거함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "cart",
      "explicit_detail_evidence": [
        "speed of the cart does not warrant an abrupt stop",
        "man to fly out"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R3",
  "summary_ko": "남자가 너무 좁은 틈을 통해 나갈 때 다리가 유리를 통과함",
  "claims": [
    {
      "id": "R3.S1",
      "evidence": "the man's legs pass through the glass as he goes out through the space which is clearly too small",
      "symptom_ko": "남자의 다리가 유리를 뚫고 통과함",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the man's legs",
      "explicit_detail_evidence": [
        "pass through the glass"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "id": "R4",
  "summary_ko": "남자가 옆으로 나가지 않고 앞쪽을 통해 나가려고 하는 동작이 상식에 맞지 않는다.",
  "claims": [
    {
      "id": "R4.S1",
      "evidence": "it does not make sense the man tries to exit through the front instead of stepping out the side",
      "symptom_ko": "남자가 옆으로 나가지 않고 앞쪽으로 나가려고 시도하여 비정상적임",
      "is_anomaly": true,
      "specificity": "specific",
      "target_evidence": "the man",
      "explicit_detail_evidence": [
        "tries to exit through the front instead of stepping out the side"
      ],
      "missing_details_ko": ""
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R1",
      "candidate_id": "C2",
      "target_relation": "same_interaction",
      "reference_claim_ids": [
        "R1.S1"
      ],
      "reference_evidence": "Man passes through the cart.",
      "candidate_evidence": "The golf cart windshield abruptly disappears as the driver moves forward over the hood.",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 남자가 카트 본체를 물리적으로 관통하여 지나가는 이상(passes through the cart)을 지적하는 반면, 후보 설명은 운전자가 후드 위로 이동할 때 골프 카트의 앞유리가 갑자기 사라지는 현상(windshield abruptly disappears)을 특정 결함으로 지적하고 있습니다. 이는 동일 상호작용 맥락 내에서 설명되는 구체적으로 구분되는 두 개의 서로 다른 결함 현상이므로 명시적 분리에 해당합니다."
    }
  ]
}

{
  "pairs": [
    {
      "reference_id": "R3",
      "candidate_id": "C2",
      "target_relation": "same_interaction",
      "reference_claim_ids": [
        "R3.S1"
      ],
      "reference_evidence": "the man's legs pass through the glass",
      "candidate_evidence": "The golf cart windshield abruptly disappears",
      "basis": "explicit_separation",
      "reason_ko": "참조 설명은 남자의 다리가 유리를 뚫고 통과하는 관통 현상(pass through)을 구체적인 결함으로 기술하고 있는 반면, 후보 설명은 골프 카트의 앞유리 자체가 완전히 사라지는 소실 현상(abruptly disappears)을 결함으로 기술하고 있어 서로 다른 구체적인 이상 현상으로 분리됩니다."
    }
  ]
}

